int32_t __fastcall SOUND_PlayFootstepSound(uint32_t nParam1, uint32_t nParam2, uint32_t nModulus) {
    int nMinDist;
    uint32_t nMod1;
    int nWrapDist;
    uint32_t nMod2 = nModulus - 1;
    if (!(nModulus & nMod2)) {
      nMod1 = nMod2 & nParam1;
      nMod2 &= nParam2;
    } else {
      nMod1 = (int)nParam1 % (int)nModulus;
      nMod2 = (int)nParam2 % (int)nModulus;
    }

    int nDiff = nMod2 - nMod1;
    int nAbsDiff = nDiff;
    if (nDiff < 0) {
      nAbsDiff = -nDiff;
    }

    nDiff -= nModulus;
    if (nDiff < 0) {
      nDiff = -nDiff;
    }

    nWrapDist = nMod1 - nMod2 - nModulus;
    if (nWrapDist < 0) {
      nWrapDist = -nWrapDist;
    }

    nMinDist = nAbsDiff;
    if (nAbsDiff >= nDiff) {
      nMinDist = nDiff;
    }
    if (nMinDist >= nWrapDist) {
      return nWrapDist;
    }

    nWrapDist = nAbsDiff;
    if (nAbsDiff < nDiff) {
      return nWrapDist;
    }

    nWrapDist = nDiff;
    return nWrapDist;
}

